//! Leptos UI for the one-page site: splash + the "find your handshake" wizard.
//!
//! The page is a splash — hero, one big invite, proof strip, footer. The
//! invite opens a modal wizard: three questions resolve to a real Noise
//! pattern, and the result card shows what you gained, the `noise!` code,
//! the pattern's frozen trace replaying (bytes generated by hiss, pinned by
//! `tests/fixtures.rs`), the alternates, and a suite recommendation. Copy is
//! lifted from the README — the page asserts nothing the crate's docs don't.

use std::time::Duration;

use leptos::ev;
use leptos::html;
use leptos::prelude::*;

use crate::fixtures::{self, Dir};

const REPO: &str = "https://github.com/primetype/hiss";
const TESTED: &str = "https://github.com/primetype/hiss#how-this-is-tested";
const PINNED: &str = "https://github.com/primetype/hiss/blob/main/site/tests/fixtures.rs";

/// Answer cards and buttons share these classes so Tailwind's scanner sees
/// them — and so everything clickable unmistakably *looks* clickable.
const ANSWER_CARD: &str = "block w-full cursor-pointer rounded-sm border border-line bg-panel-2 \
     p-4 text-left transition-colors hover:border-cyan hover:bg-cyan/5";
const GHOST_BTN: &str = "cursor-pointer text-xs text-silver-faint hover:text-cyan";
const TAB_ON: &str =
    "cursor-pointer rounded-sm border border-cyan bg-cyan/10 px-3 py-1.5 text-xs text-cyan";
const TAB_OFF: &str = "cursor-pointer rounded-sm border border-line px-3 py-1.5 text-xs \
     text-silver-dim transition-colors hover:border-silver-faint hover:text-silver";

/// rustc's rejection of a pattern that never keys the cipher — the Noise
/// §7.3 guard. Quoted from the README, where it is pinned by a
/// `compile_fail` doctest on `WellFormed`; text verbatim, wrapping tidied.
const NEVER_KEYS_DIAG: &str = r#": this Noise pattern never keys the cipher: it performs no DH
              (ee/es/se/ss) and no psk token, so it provides no confidentiality
              or authentication
 --> src/main.rs:3:9
  |
3 |     pub Bad<X25519, ChaChaPoly, Blake2b> {
  |         ^^^ pattern finalises with an unkeyed cipher"#;

#[component]
pub fn App() -> impl IntoView {
    let wizard_open = RwSignal::new(false);
    // The invite button, so the wizard can hand keyboard focus back on close.
    let invite_btn = NodeRef::<html::Button>::new();
    view! {
        // `inert` while the wizard is open: the page behind the modal stops
        // being focusable or clickable, which is the whole focus trap.
        <main
            class="flex min-h-dvh flex-col px-5 md:px-10"
            inert=move || wizard_open.get().then_some("")
        >
            <Nav />
            <div class="mx-auto flex w-full max-w-6xl flex-1 flex-col justify-center gap-12 py-12 lg:flex-row lg:items-center lg:gap-20">
                <Hero />
                <Invite open=wizard_open btn=invite_btn />
            </div>
            <div class="mx-auto w-full max-w-6xl pb-6">
                <div class="static-band mb-6"></div>
                <ProofStrip />
                <PageFooter />
            </div>
        </main>
        <Wizard open=wizard_open invite_btn=invite_btn />
    }
}

